arguments.command:
cd /workspace/submission && rm -rf __pycache__ && python3 - <<'EOF'
import os,stat
entries=0;total=0;bad=[]
for root,ds,fs in os.walk('.'):
    entries+=len(ds)+len(fs)
    for name in ds+fs:
        p=os.path.join(root,name);st=os.lstat(p)
        if stat.S_ISDIR(st.st_mode):
            if stat.S_ISLNK(st.st_mode):bad.append(p)
        else:
            total+=st.st_size
            if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1:bad.append(p)
print('entries',entries,'bytes',total,'bad',bad)
for root,ds,fs in os.walk('.'):
    for f in sorted(fs):print(os.path.join(root,f),os.path.getsize(os.path.join(root,f)))
EOF
